"""Build the expanded AI units without changing material IDs or other subjects."""
from pathlib import Path
from html import escape as E
import json
R=Path(__file__).resolve().parent
catalog=json.loads((R/'catalog.json').read_text())
css='''*{box-sizing:border-box}body{font:18px/1.75 Georgia,serif;color:#19333d;background:#faf9f5;margin:0}main{max-width:940px;margin:auto;padding:45px 25px 90px}h1,h2,h3,nav,label,button,summary{font-family:system-ui,sans-serif;line-height:1.35}h1{font-size:clamp(33px,5vw,48px);line-height:1.13;margin:28px 0}h2{font-size:27px;margin:0 0 20px}h3{font-size:19px}p{max-width:800px}a{color:#176398}nav{display:flex;gap:18px;flex-wrap:wrap;font-size:15px}section{padding:34px 0;border-top:1px solid #d5dfda;scroll-margin-top:18px}.worked,.box,.practice,details{padding:21px;border:1px solid #cbdad3;border-radius:9px;margin:22px 0}.worked{background:#edf3ef}.practice{background:#eef3f8;border-left:4px solid #246793}.box{background:#f4efe5}.worked p:first-child,.box p:first-child{margin-top:0}.worked p:last-child,.box p:last-child{margin-bottom:0}details{background:#fff}summary{cursor:pointer;font-size:16px;font-weight:600}li{margin:10px 0}.table-scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:350px;font-size:16px}td,th{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid #cad8d1}pre{overflow-x:auto;padding:18px;background:white;border-radius:8px;font:16px/1.5 monospace}textarea,select{font:16px/1.5 system-ui,sans-serif;width:100%;padding:12px;border:1px solid #94aaa0;border-radius:5px;background:white}label{display:block;font-size:14px;margin:14px 0}textarea{min-height:110px}button{cursor:pointer;padding:11px 18px;border-radius:6px;border:1px solid #617e72;background:white;color:#19333d}.small,[role=status]{font:14px/1.6 system-ui,sans-serif;color:#49655a}.eyebrow{font:600 12px system-ui,sans-serif;letter-spacing:1px;text-transform:uppercase;color:#267060}.link-list{display:flex;flex-wrap:wrap;gap:10px;font:14px/1.5 system-ui,sans-serif}.link-list a{border:1px solid #cbdad3;border-radius:18px;padding:6px 12px;text-decoration:none}article p,section p,li{overflow-wrap:anywhere}@media(max-width:550px){main{padding:28px 18px 60px}.worked,.practice,.box,details{padding:16px}h2{font-size:24px}}@media print{body{background:white;font-size:12pt}main{max-width:none;padding:0}textarea,select,button,[role=status]{display:none}details>*{display:block}h2,h3{break-after:avoid}.practice,.worked{break-inside:avoid}}'''
(R/'lesson.css').write_text(css)
EXTRAS={
2:[('A new graph has S→A cost 3, S→G cost 10, A→G cost 1. Estimates are h(S)=4,h(A)=1,h(G)=0. Compare greedy and A*.','Greedy chooses G immediately and returns cost 10. A* first chooses A with f=3+1=4, then improves G to cost 4.'),('The true remaining costs in that graph are 4,1,0. Check h(S)=3,h(A)=1,h(G)=0 for admissibility and consistency.','It is admissible. Consistency checks are 3≤3+1, 1≤1+0 and 3≤10+0, all true.')],
3:[('A MAX root has two MIN children with leaves (5,8) and (4,7). Find the minimax value and trace left-to-right pruning.','The children have values 5 and 4, so MAX chooses the first with value 5. After the second child reveals 4, beta=4≤alpha=5, so skip its 7.'),('Reverse the order of those two MIN children. Can the same leaves be skipped?','The (4,7) child is evaluated first and returns 4. The (5,8) child then reveals 5, which does not permit a cutoff at alpha=4. Both its leaves must be examined. Root value remains 5.')],
4:[('Do P∨Q and ¬P entail Q? Give a short argument.','Yes. At least one of P,Q must be true. Since P is false, Q must be true.'),('On the integer domain, compare ∀x∃y(y>x) with ∃y∀x(y>x).','The first is true: choose y=x+1 for each x. The second is false: for any fixed y, choose x=y, so y>x fails.')],
5:[('A binary root X has a binary child Y. Now Y also has a binary parent Z, independent of X. How many free numbers specify P(X),P(Z),P(Y|X,Z)?','One for X, one for Z, and four for Y’s four parent configurations: 6 free probabilities.'),('For A←B→C, what graph condition makes A and C independent once B is known?','The shown fork is the only path between A and C. Conditioning on the non-collider B blocks it. In a larger graph, any other paths must also be blocked.')],
6:[('Weights for a binary query are 0.06 and 0.14. Normalize them and state the evidence probability if these are the only unnormalized joint weights.','The evidence probability is 0.20. The posterior probabilities are 0.3 and 0.7.'),('Factors a(U,V) and b(V,W) use variables with 2,3 and 2 values for U,V,W. After multiplying and summing out V, how many product entries and output entries are possible?','The product has 2×3×2=12 entries. The resulting factor on U,W has 2×2=4 entries.')],
7:[('Five samples match the evidence, and three satisfy the query. What rejection-sampling estimate follows?','3/5=0.6. The denominator counts accepted samples.'),('Four weighted samples have weights 0.2,0.4,0.1,0.3. The query is true in the first and third. Find its weighted estimate.','The query weight is 0.2+0.1=0.3; total weight is 1.0, so the estimate is 0.3.')]
}
SOURCES={2:'search/informed.html',3:'games/minimax.html',4:'logic/',5:'bayes-nets/representation.html',6:'bayes-nets/elimination.html',7:'bayes-nets/approximate.html'}
def paragraph(text):return '<p>'+E(text)+'</p>'
def practice(ident,prompt,answer,scored=False):
 return f'''<article class="practice" data-practice="{ident}"><p class="eyebrow">{'Keep this numbered answer for your upload' if scored else 'Pause and try one step'}</p><h3>{E(ident)}</h3>{paragraph(prompt)}<label>Your attempt<textarea data-response="{ident}" aria-label="Your attempt for {ident}" placeholder="Write your own answer before opening the worked check."></textarea></label><label>Help used<select data-help="{ident}"><option>Not recorded</option><option>Without notes</option><option>Lesson example used</option><option>Hint used</option><option>Worked answer used</option></select></label><details data-check="{ident}"><summary>Worked check · open after attempting</summary>{paragraph(answer)}</details></article>'''
manifest=[]
for n in range(2,8):
 d=json.loads((R/'lesson-data'/f'unit-{n:02}.json').read_text());w=catalog[n-1]['weeks'][0];title=d['title'];body=f'''<nav><a href="index.html">AI course</a><a href="day-{n-1:02}.html">Previous lesson</a><a href="/">Aleph dashboard</a></nav><p class="eyebrow">AI unit {n} · explain, practise, check, remember</p><h1>{E(title)}</h1>{paragraph(d['intro'])}<div class="box"><p>Work through one section at a time. Follow its example, then attempt the small question. If you need an explanation or a worked answer, record that help. These lessons are practice, not proof that you can already solve every variation.</p><p class="small">A 90-minute session is a suggested budget. Stop at a section boundary if needed. Your notes save on this browser only. Export them before changing devices. Submit through the existing AI material card.</p></div><div class="link-list">'''+''.join(f'<a href="#step-{i}">Step {i}</a>' for i in range(1,len(d['sections'])+1))+'</div><p role="status" data-save-status>Optional notes are stored on this browser. No work has been submitted.</p>'
 warm=0
 for i,s in enumerate(d['sections'],1):
  body+=f'<section id="step-{i}" data-teaching-step><h2>{E(s["title"])}</h2>'+''.join(paragraph(t) for t in s['text'])+'<div class="worked"><h3>Follow the reasoning</h3>'+s['example']+'</div>'
  if s.get('graded'):
   q=s['graded'];ident=f'AI{n:02}-Q{q}';prompt=w['inlineQuestions'][q-1].split(': ',1)[1];answer=w['modelLesson']['gradingKeys'][ident];body+=practice(ident,prompt,answer,True)
  else:
   warm+=1;body+=practice(f'AI{n:02}-W{warm}',s['question'],s['answer'])
  body+='</section>'
 body+='<section><h2>How the ideas connect</h2><ul>'+''.join('<li>'+E(x)+'</li>' for x in d['remember'])+'</ul><h2>Use the ideas on a different problem</h2><p>Try these after the main lesson. If the method still feels uncertain, ask for another similar problem before increasing the difficulty.</p>'
 for j,(q,a) in enumerate(EXTRAS[n],1):body+=practice(f'AI{n:02}-R{j}',q,a)
 body+='<h2>Return to this on a later day</h2>'+paragraph(d['review'])+'<p>Review material you actually practised. Begin without the notes. If you need help, use it and record it. Ask your tutor to choose another problem before treating the result as independent recall.</p><h2>Keep the original work and the corrections separate</h2><p>The export includes your notes, help used and the attempt recorded when you first opened each worked check. It does not grade the work or complete an assignment.</p><button type="button" data-export>Export my AI practice</button><button type="button" onclick="window.print()">Print lesson</button></section>'
 body+=f'<footer><p class="small">Content references: <a href="https://inst.eecs.berkeley.edu/~cs188/textbook/{SOURCES[n]}">Berkeley CS188</a>, <a href="https://aima.cs.berkeley.edu/">AIMA, fourth edition</a>, and the <a href="https://gate2027.iitm.ac.in/static/doc/GATE2027_Syllabus/DA_GATE2027_Syllabus.pdf">official GATE DA syllabus</a>. Teaching approach: <a href="study-method.html">the Skycak tutor skill</a>. The questions here are original practice examples.</p></footer>'
 if n<7:body+=f'<nav><a href="day-{n+1:02}.html">Next lesson →</a></nav>'
 # Tables must scroll inside their own container on small screens.
 body=body.replace('<table>','<div class="table-scroll"><table>').replace('</table>','</table></div>')
 page=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} · Aleph AI</title><link rel="stylesheet" href="lesson.css"><script defer src="lesson-workspace.js"></script></head><body><main data-ai-unit="{n:02}">{body}</main></body></html>'
 (R/f'day-{n:02}.html').write_text(page)
 manifest.append(dict(unit=n,sections=len(d['sections']),scoredQuestionIds=list(w['modelLesson']['gradingKeys']),warmups=warm,additionalPractice=len(EXTRAS[n])))
(R/'lesson-data'/'manifest.json').write_text(json.dumps(manifest,indent=2))
print('Built six lessons with',sum(m['sections'] for m in manifest),'small teaching cycles and stable scored question IDs.')
